/** @public @react */
export function CopyAsMenuGroup() {
	const editor = useEditor()
	const actions = useActions()
	const atLeastOneShapeOnPage = useHasShapesOnPage()
	const isDebugMode = useValue('isDebugMode', () => editor.getInstanceState().isDebugMode, [editor])

	// Don't render the submenu if none of its copy actions are available. Otherwise the
	// trigger would open onto just the background toggle with nothing to copy.
	const hasCopyAsSvg = Boolean(actions['copy-as-svg'])
	const hasCopyAsPng =
		Boolean(actions['copy-as-png']) &&
		Boolean(editor.getContainerWindow().navigator.clipboard?.write)
	const hasCopyAsJson = isDebugMode && Boolean(actions['copy-as-json'])
	if (!hasCopyAsSvg && !hasCopyAsPng && !hasCopyAsJson) return null

	return (
		<TldrawUiMenuSubmenu
			id="copy-as"
			label="context-menu.copy-as"
			size="small"
			disabled={!atLeastOneShapeOnPage}
		>
			<TldrawUiMenuGroup id="copy-as-group">
				{hasCopyAsSvg && <TldrawUiMenuActionItem actionId="copy-as-svg" />}
				{hasCopyAsPng && <TldrawUiMenuActionItem actionId="copy-as-png" />}
				{hasCopyAsJson && <TldrawUiMenuActionItem actionId="copy-as-json" />}
			</TldrawUiMenuGroup>
			<TldrawUiMenuGroup id="copy-as-bg">
				<ToggleTransparentBgMenuItem />
			</TldrawUiMenuGroup>
		</TldrawUiMenuSubmenu>
	)
}

/** @public @react */
export function CutMenuItem() {
	const canApplySelectionAction = useCanApplySelectionAction()
	const hasUnlockedShapes = useUnlockedSelectedShapesCount(1)

	return (
		<TldrawUiMenuActionItem
			actionId="cut"
			disabled={!canApplySelectionAction || !hasUnlockedShapes}
		/>
	)
}

/** @public @react */
export function CopyMenuItem() {
	const canApplySelectionAction = useCanApplySelectionAction()

	return <TldrawUiMenuActionItem actionId="copy" disabled={!canApplySelectionAction} />
}

/** @public @react */
export function PasteMenuItem() {
	const shouldDisplay = showMenuPaste

	return <TldrawUiMenuActionItem actionId="paste" disabled={!shouldDisplay} />
}

/* ------------------- Conversions ------------------ */

/** @public @react */
export function ExportAsMenuGroup() {
	const actions = useActions()

	// Don't render the submenu if none of its export actions are available. Otherwise the
	// trigger would open onto just the background toggle with nothing to export.
	const hasExportAsSvg = Boolean(actions['export-as-svg'])
	const hasExportAsPng = Boolean(actions['export-as-png'])
	if (!hasExportAsSvg && !hasExportAsPng) return null

	return (
		<TldrawUiMenuSubmenu id="export-as" label="context-menu.export-as" size="small">
			<TldrawUiMenuGroup id="export-as-group">
				{hasExportAsSvg && <TldrawUiMenuActionItem actionId="export-as-svg" />}
				{hasExportAsPng && <TldrawUiMenuActionItem actionId="export-as-png" />}
			</TldrawUiMenuGroup>
			<TldrawUiMenuGroup id="export-as-bg">
				<ToggleTransparentBgMenuItem />
			</TldrawUiMenuGroup>
		</TldrawUiMenuSubmenu>
	)
}

