// Regression: removing every action inside a conversions submenu (copy-as or export-as)
// used to leave the submenu trigger visible, opening onto just the background toggle. The
// trigger should disappear when none of its copy/export actions remain.
it('hides the copy-as and export-as submenus when their actions are removed', async () => {
	const id = createShapeId()
	await renderTldrawComponent(
		<Tldraw
			overrides={{
				actions: (_editor, actions) => {
					const next = { ...actions }
					delete next['copy-as-svg']
					delete next['copy-as-png']
					delete next['copy-as-json']
					delete next['export-as-svg']
					delete next['export-as-png']
					return next
				},
			}}
			onMount={(editor) => {
				editor.createShape({ id, type: 'geo' })
				editor.select(id)
			}}
		/>,
		{ waitForPatterns: false }
	)
	const canvas = await screen.findByTestId('canvas')

	fireEvent.contextMenu(canvas)
	await screen.findByTestId('context-menu')

	expect(screen.queryByTestId('context-menu-sub.copy-as-button')).toBeNull()
	expect(screen.queryByTestId('context-menu-sub.export-as-button')).toBeNull()
})

